import streamlit as st
import pandas as pd
import os

st.title("MARKET CAP: High Return & Deep Discount Screener")

st.sidebar.header("Screener Filters")
market_cap_filter = st.sidebar.radio(
    "Filter by Market Cap",
    ["Show All", "Category A (> ₹20k Cr)", "Category B (< ₹20k Cr)"]
)

# Reading the static file generated by GitHub Actions (using market_cap_screener.py)
file_path = "market_cap_results.csv"

if os.path.exists(file_path):
    df = pd.read_csv(file_path)
    
    if df.empty:
        st.warning("No companies currently meet all strict criteria in the Indian market.")
    else:
        if market_cap_filter != "Show All":
            display_df = df[df['Category'] == market_cap_filter].drop(columns=['RawMarketCap'], errors='ignore')
        else:
            display_df = df.drop(columns=['RawMarketCap'], errors='ignore')
            
        if display_df.empty:
            st.warning(f"No companies found in {market_cap_filter} meeting the criteria.")
        else:
            st.dataframe(display_df.style.format({
                'MarketCap (Cr)': '₹{:,.0f}',
                'ROE': '{:.1%}',
                'ROCE': '{:.1%}',
                'ATH': '₹{:.2f}',
                'CMP': '₹{:.2f}'
            }), use_container_width=True)
else:
    st.info("Data is currently being generated by the backend pipeline. Please check back later.")
